-- CounterNest POS Phase 33.6: operational scheduling and attendance (not payroll).
create table public.staff_shift_assignments(
  id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,staff_user_id uuid not null references auth.users(id) on delete restrict,
  shift_date date not null,start_time time not null,end_time time not null,role_note text,location_note text,status text not null default 'scheduled' check(status in('scheduled','completed','cancelled')),
  created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_by uuid references auth.users(id) on delete restrict,updated_at timestamptz not null default now(),
  check(end_time>start_time),unique(shop_id,staff_user_id,shift_date,start_time)
);
create table public.staff_attendance_entries(
  id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,staff_user_id uuid not null references auth.users(id) on delete restrict,
  shift_assignment_id uuid references public.staff_shift_assignments(id) on delete restrict,business_date date not null,clock_in_at timestamptz not null default now(),clock_in_note text,
  clock_out_at timestamptz,clock_out_note text,status text not null default 'open' check(status in('open','closed','corrected')),created_at timestamptz not null default now()
);
create table public.staff_attendance_events(
  id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,attendance_id uuid references public.staff_attendance_entries(id) on delete restrict,shift_assignment_id uuid references public.staff_shift_assignments(id) on delete restrict,
  action text not null,note text,details jsonb not null default '{}'::jsonb,performed_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now()
);
create unique index staff_attendance_one_open on public.staff_attendance_entries(shop_id,staff_user_id) where status='open';
create index staff_shift_date_idx on public.staff_shift_assignments(shop_id,shift_date,start_time);create index attendance_date_idx on public.staff_attendance_entries(shop_id,business_date,clock_in_at);
alter table public.staff_shift_assignments enable row level security;alter table public.staff_attendance_entries enable row level security;alter table public.staff_attendance_events enable row level security;
create policy shift_assignment_read on public.staff_shift_assignments for select to authenticated using(shop_id=public.current_shop_id() and(public.is_admin() or staff_user_id=auth.uid()));
create policy attendance_read on public.staff_attendance_entries for select to authenticated using(shop_id=public.current_shop_id() and(public.is_admin() or staff_user_id=auth.uid()));
create policy attendance_events_read on public.staff_attendance_events for select to authenticated using(shop_id=public.current_shop_id() and(public.is_admin() or exists(select 1 from public.staff_attendance_entries a where a.id=attendance_id and a.staff_user_id=auth.uid())));

create or replace function public.create_staff_shift(p_staff_user_id uuid,p_shift_date date,p_start_time time,p_end_time time,p_role_note text default null,p_location_note text default null) returns uuid language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_id uuid;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if p_shift_date is null or p_start_time is null or p_end_time is null or p_end_time<=p_start_time then raise exception 'Valid date and shift times are required';end if;if not exists(select 1 from public.staff_profiles where shop_id=v_shop and user_id=p_staff_user_id and active) then raise exception 'Active staff member not found';end if;if exists(select 1 from public.staff_shift_assignments where shop_id=v_shop and staff_user_id=p_staff_user_id and shift_date=p_shift_date and status='scheduled' and p_start_time<end_time and p_end_time>start_time) then raise exception 'This staff member has an overlapping shift';end if;insert into public.staff_shift_assignments(shop_id,staff_user_id,shift_date,start_time,end_time,role_note,location_note,created_by,updated_by) values(v_shop,p_staff_user_id,p_shift_date,p_start_time,p_end_time,nullif(trim(p_role_note),''),nullif(trim(p_location_note),''),auth.uid(),auth.uid()) returning id into v_id;insert into public.staff_attendance_events(shop_id,shift_assignment_id,action,note,performed_by) values(v_shop,v_id,'shift_scheduled',nullif(trim(p_role_note),''),auth.uid());return v_id;end $$;

create or replace function public.cancel_staff_shift(p_shift_id uuid,p_note text) returns void language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_row public.staff_shift_assignments%rowtype;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if length(trim(coalesce(p_note,'')))<3 then raise exception 'Cancellation note is required';end if;select * into v_row from public.staff_shift_assignments where id=p_shift_id and shop_id=v_shop for update;if v_row.id is null or v_row.status<>'scheduled' then raise exception 'Scheduled shift not found';end if;update public.staff_shift_assignments set status='cancelled',updated_by=auth.uid(),updated_at=now() where id=v_row.id;insert into public.staff_attendance_events(shop_id,shift_assignment_id,action,note,performed_by) values(v_shop,v_row.id,'shift_cancelled',trim(p_note),auth.uid());end $$;

create or replace function public.clock_in_staff(p_shift_id uuid default null,p_note text default null) returns uuid language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_id uuid;v_shift public.staff_shift_assignments%rowtype;begin if auth.uid() is null or v_shop is null then raise exception 'Active staff access required';end if;if exists(select 1 from public.staff_attendance_entries where shop_id=v_shop and staff_user_id=auth.uid() and status='open') then raise exception 'You are already clocked in';end if;if p_shift_id is not null then select * into v_shift from public.staff_shift_assignments where id=p_shift_id and shop_id=v_shop and staff_user_id=auth.uid() and status='scheduled';if v_shift.id is null then raise exception 'Assigned scheduled shift not found';end if;end if;insert into public.staff_attendance_entries(shop_id,staff_user_id,shift_assignment_id,business_date,clock_in_note) values(v_shop,auth.uid(),p_shift_id,current_date,nullif(trim(p_note),'')) returning id into v_id;insert into public.staff_attendance_events(shop_id,attendance_id,shift_assignment_id,action,note,performed_by) values(v_shop,v_id,p_shift_id,'clocked_in',nullif(trim(p_note),''),auth.uid());return v_id;end $$;

create or replace function public.clock_out_staff(p_note text default null) returns void language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_row public.staff_attendance_entries%rowtype;begin if auth.uid() is null or v_shop is null then raise exception 'Active staff access required';end if;select * into v_row from public.staff_attendance_entries where shop_id=v_shop and staff_user_id=auth.uid() and status='open' for update;if v_row.id is null then raise exception 'No open attendance record found';end if;update public.staff_attendance_entries set status='closed',clock_out_at=now(),clock_out_note=nullif(trim(p_note),'') where id=v_row.id;if v_row.shift_assignment_id is not null then update public.staff_shift_assignments set status='completed',updated_by=auth.uid(),updated_at=now() where id=v_row.shift_assignment_id and status='scheduled';end if;insert into public.staff_attendance_events(shop_id,attendance_id,shift_assignment_id,action,note,performed_by) values(v_shop,v_row.id,v_row.shift_assignment_id,'clocked_out',nullif(trim(p_note),''),auth.uid());end $$;

create or replace function public.get_staff_schedule_board(p_from date default null,p_to date default null) returns jsonb language plpgsql security definer stable set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_from date:=coalesce(p_from,current_date-7);v_to date:=coalesce(p_to,current_date+14);begin if auth.uid() is null or v_shop is null then raise exception 'Active staff access required';end if;if v_to<v_from or v_to-v_from>62 then raise exception 'Date range must be 62 days or less';end if;return jsonb_build_object(
  'is_admin',public.is_admin(),'staff',(select coalesce(jsonb_agg(jsonb_build_object('user_id',s.user_id,'display_name',s.display_name,'role',s.role) order by s.display_name),'[]'::jsonb) from public.staff_profiles s where s.shop_id=v_shop and s.active and(public.is_admin() or s.user_id=auth.uid())),
  'open_attendance',(select to_jsonb(x) from(select a.id,a.shift_assignment_id,a.clock_in_at,a.clock_in_note from public.staff_attendance_entries a where a.shop_id=v_shop and a.staff_user_id=auth.uid() and a.status='open')x),
  'shifts',(select coalesce(jsonb_agg(to_jsonb(x) order by x.shift_date,x.start_time),'[]'::jsonb) from(select s.id,s.staff_user_id,s.shift_date,s.start_time,s.end_time,s.role_note,s.location_note,s.status,sp.display_name,exists(select 1 from public.staff_attendance_entries a where a.shift_assignment_id=s.id) attendance_recorded from public.staff_shift_assignments s join public.staff_profiles sp on sp.shop_id=s.shop_id and sp.user_id=s.staff_user_id where s.shop_id=v_shop and s.shift_date between v_from and v_to and(public.is_admin() or s.staff_user_id=auth.uid()))x),
  'attendance',(select coalesce(jsonb_agg(to_jsonb(x) order by x.clock_in_at desc),'[]'::jsonb) from(select a.id,a.staff_user_id,a.business_date,a.clock_in_at,a.clock_out_at,a.status,a.clock_in_note,a.clock_out_note,sp.display_name,round(extract(epoch from(coalesce(a.clock_out_at,now())-a.clock_in_at))/3600.0,2) hours from public.staff_attendance_entries a join public.staff_profiles sp on sp.shop_id=a.shop_id and sp.user_id=a.staff_user_id where a.shop_id=v_shop and a.business_date between v_from and v_to and(public.is_admin() or a.staff_user_id=auth.uid()))x));end $$;

alter function public.export_business_backup() rename to export_business_backup_phase335_base;revoke all on function public.export_business_backup_phase335_base() from public;revoke all on function public.export_business_backup_phase335_base() from authenticated;
create or replace function public.export_business_backup() returns jsonb language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_base jsonb;v_export uuid;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;v_base:=public.export_business_backup_phase335_base();v_export:=(v_base->>'export_id')::uuid;update public.backup_exports set schema_version='1.19.0' where id=v_export and shop_id=v_shop;return(v_base-'schema_version')||jsonb_build_object('schema_version','1.19.0','staff_shift_assignments',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.staff_shift_assignments t where shop_id=v_shop),'staff_attendance_entries',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.staff_attendance_entries t where shop_id=v_shop),'staff_attendance_events',(select coalesce(jsonb_agg(to_jsonb(t)),'[]'::jsonb) from public.staff_attendance_events t where shop_id=v_shop));end $$;
revoke all on function public.create_staff_shift(uuid,date,time,time,text,text) from public;revoke all on function public.cancel_staff_shift(uuid,text) from public;revoke all on function public.clock_in_staff(uuid,text) from public;revoke all on function public.clock_out_staff(text) from public;revoke all on function public.get_staff_schedule_board(date,date) from public;revoke all on function public.export_business_backup() from public;
grant execute on function public.create_staff_shift(uuid,date,time,time,text,text) to authenticated;grant execute on function public.cancel_staff_shift(uuid,text) to authenticated;grant execute on function public.clock_in_staff(uuid,text) to authenticated;grant execute on function public.clock_out_staff(text) to authenticated;grant execute on function public.get_staff_schedule_board(date,date) to authenticated;grant execute on function public.export_business_backup() to authenticated;
